preConditionHook:
// Mirrors the EL twin statement for statement: an outer scan over every
// candidate run start kk in 0 .. windowBars - swingBars, an inner scan of the
// swingBars pairs from that start. The run tests are ordinary EL relational
// operators, so el_ge/el_le carry the measured 2.22e-12 tolerance -- an equal
// high (within tolerance) breaks the lower-high run, and an equal low breaks
// the higher-low run.
// EL does not short-circuit and neither does this loop: both directions are
// evaluated on every pair, so the two libraries touch the same bars.
foundDown = false;
foundUp = false;
for (int k = 0; k <= (int)windowBars - (int)swingBars; ++k) {
    runDown = true;
    runUp = true;
    for (int j = k; j <= k + (int)swingBars - 1; ++j) {
        if (el_ge(high[j], high[j + 1])) runDown = false;
        if (el_le(low[j], low[j + 1])) runUp = false;
    }
    if (runDown) foundDown = true;
    if (runUp) foundUp = true;
}
